const { ethers } = require("ethers");
require("dotenv").config();
const axios = require("axios");
const { decideChains } = require("../../../config/provider");

const PHANTOM_ADDRESS = "0x0000000000000000000000000000000000008888";
const HONEYPOT_BYTECODE =
  "";
const ANVIL_URL = "http://127.0.0.1:8545";
const RICH_WHALE = "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266";

const ROUTERS = {
  1: "0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D", // uniswapV2
};

// routerABI
const routerABI = [
  "function swapExactETHForTokensSupportingFeeOnTransferTokens(uint amountOutMin, address[] calldata path, address to, uint deadline) external payable",
  "function swapExactTokensForETHSupportingFeeOnTransferTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external",
  "function getAmountsOut(uint amountIn, address[] calldata path) external view returns (uint[] memory amounts)",
  "function WETH() external pure returns (address)",
];

// defination of ABI
const HONEYPOT_ABI = [
  {
    inputs: [
      { internalType: "address", name: "targetContract", type: "address" },
      { internalType: "address", name: "dexRouter", type: "address" },
    ],
    name: "checkContract",
    outputs: [
      {
        components: [
          { internalType: "bool", name: "isBlackListDetected", type: "bool" },
          { internalType: "bool", name: "isMintable", type: "bool" },
          { internalType: "bool", name: "isTradingControl", type: "bool" },
          { internalType: "uint256", name: "buyTax", type: "uint256" },
          { internalType: "uint256", name: "sellTax", type: "uint256" },
          { internalType: "uint8", name: "riskScore", type: "uint8" },
          { internalType: "string", name: "errorReason", type: "string" },
        ],
        internalType: "struct HoneypotBase.HoneypotBaseResult",
        name: "",
        type: "tuple",
      },
    ],
    stateMutability: "payable",
    type: "function",
  },
];

const iface = new ethers.Interface(HONEYPOT_ABI);
const alchemyProvider = decideChains("ETH");

const anvilProvider = new ethers.JsonRpcProvider(ANVIL_URL, 1, {
  staticNetwork: true,
});

/**
 * @param {*} tokenAddress
 * @param {*} dex_routerAddress
 * @process =>
 *  1. setup a new fork using anvil
 *  2. Swap tokens in buying for ETH
 *  3. Swap back in Sell for the token
 * @returns Json response => {buyTax, sellTax}
 */

async function _simulateAccurateTax(token, router) {
  // 1. Setup the Whale (Payer)
  await anvilProvider.send("anvil_impersonateAccount", [RICH_WHALE]);
  await anvilProvider.send("anvil_setBalance", [
    RICH_WHALE,
    "0x100000000000000000000000000",
  ]);
  const signer = await anvilProvider.getSigner(RICH_WHALE);

  // 2. Setup a "Clean" Recipient (Receiver)
  // We send profits here so Gas costs don't mess up the math
  const RECIPIENT = ethers.Wallet.createRandom().address;

  const weth = await new ethers.Contract(
    router,
    ["function WETH() view returns (address)"],
    anvilProvider,
  ).WETH();
  const routerContract = new ethers.Contract(router, routerABI, signer);
  const tokenContract = new ethers.Contract(
    token,
    [
      "function balanceOf(address) view returns (uint256)",
      "function approve(address,uint256)",
    ],
    signer,
  );

  const ethAmount = ethers.parseEther("0.1");

  // BUY SIMULATION
  const startToken = await tokenContract.balanceOf(RICH_WHALE);

  await routerContract.swapExactETHForTokensSupportingFeeOnTransferTokens(
    0,
    [weth, token],
    RICH_WHALE, // Whale gets the tokens
    Math.floor(Date.now() / 1000) + 300,
    { value: ethAmount, gasLimit: 30000000 },
  );

  const afterTokenBalance = await tokenContract.balanceOf(RICH_WHALE);
  const tokensReceived = afterTokenBalance - startToken;

  const expectedBuy = await routerContract.getAmountsOut(ethAmount, [
    weth,
    token,
  ]);

  let buyTax = 0n;
  if (expectedBuy[1] > 0n) {
    buyTax = ((expectedBuy[1] - tokensReceived) * 100n) / expectedBuy[1];
  }

  // SELL SIMULATION
  // Approve router to take tokens from Whale
  await tokenContract.approve(router, tokensReceived);

  // We don't need to check StartETH because RECIPIENT starts at 0
  await routerContract.swapExactTokensForETHSupportingFeeOnTransferTokens(
    tokensReceived,
    0,
    [token, weth],
    RECIPIENT, // <--- CRITICAL FIX: Send ETH to the clean bucket
    Math.floor(Date.now() / 1000) + 300,
    { gasLimit: 30000000 },
  );

  // Check the Clean Bucket's balance.
  // Since it paid no gas, this is the PURE ETH received.
  const ethReceived = await anvilProvider.getBalance(RECIPIENT);

  const expectedSell = await routerContract.getAmountsOut(tokensReceived, [
    token,
    weth,
  ]);

  let sellTax = 0n;
  if (expectedSell[1] > 0n) {
    sellTax = ((expectedSell[1] - ethReceived) * 100n) / expectedSell[1];
  }

  return { buyTax: Number(buyTax), sellTax: Number(sellTax) };
}

/**
 * @param {*} targetContractAddress
 * @param {*} dexRouter
 * @call_to_alchemyNode `eth_call` which siliently call our Phantom_Contract
 * @returns Json response
 */

const _runHoneypotCheck = async (targetContract, chainId = 1) => {
  try {
    const dexRouterAddress = ROUTERS[chainId];

    const phantomContractCallData = iface.encodeFunctionData("checkContract", [
      targetContract,
      dexRouterAddress,
    ]);

    // this will tell node(alchemy) to assume it has bytecode so run the call
    const phantomPayload = {
      id: 1,
      jsonrpc: "2.0",
      method: "eth_call",
      params: [
        {
          from: targetContract,
          to: PHANTOM_ADDRESS,
          data: phantomContractCallData,
          gas: "0xF4240",
        },
        "latest",
        {
          // state_overrides for our Contract
          [PHANTOM_ADDRESS]: {
            code: HONEYPOT_BYTECODE,
            balance: "0xffffffffffffffffffffffff",
          },
        },
      ],
    };

    const phantomResult = await alchemyProvider.send(
      phantomPayload.method,
      phantomPayload.params,
    );

    const decoded = iface.decodeFunctionResult(
      "checkContract",
      phantomResult,
    )[0];

    const result = {
      riskScore: Number(decoded.riskScore),
      hasBlackListDetected: decoded.isBlackListDetected,
      hasMintable: decoded.isMintable,
      hasTradingControl: decoded.isTradingControl,
      buyingTax: Number(decoded.buyTax),
      sellingTax: Number(decoded.sellTax),
      errorReason: decoded.errorReason,
    };

    // tax override for anvil fork
    try {
      const accurate = await _simulateAccurateTax(
        targetContract,
        dexRouterAddress,
      );
      result.buyingTax = accurate.buyTax;
      result.sellingTax = accurate.sellTax;
      // now adjusting riskScore according to what we get from buying/selling tax
      if (accurate.buyTax > 20 || accurate.sellTax > 20) result.riskScore += 30;
      if (accurate.buyTax > 90 || accurate.sellTax > 90) result.riskScore = 100;
    } catch (taxError) {
      throw new Error(`Honeypot Service Tax Error: ${taxError.message}`);
    }

    return result;
  } catch (err) {
    console.error(`Honeypot Fatal Error: ${err.message}`);
    throw err;
  }
};

module.exports = _runHoneypotCheck;
